import type { ProviderEnv } from "./types.ts";
import { getProviderEnvValue } from "./utils/provider-env.ts";

/** Required: base URL for an OpenAI-compatible summarisation endpoint. */
export const PI_SUMMARIZER_BASE_URL_ENV = "PI_SUMMARIZER_BASE_URL";
/** Required: model identifier passed to the override endpoint (e.g. "deepseek-chat"). */
export const PI_SUMMARIZER_MODEL_ENV = "PI_SUMMARIZER_MODEL";
/** Required: API key for the override endpoint. */
export const PI_SUMMARIZER_API_KEY_ENV = "PI_SUMMARIZER_API_KEY";

/** Resolved env-var override that routes context summarisation to a separate model. */
export interface SummariserEnvOverride {
	/** Model identifier passed to the override provider. */
	model: string;
	/** Base URL for an OpenAI-compatible API endpoint. */
	baseUrl: string;
	/** API key for the override endpoint. */
	apiKey: string;
}

/**
 * Resolve the {@link PI_SUMMARIZER_BASE_URL_ENV} / {@link PI_SUMMARIZER_MODEL_ENV} /
 * {@link PI_SUMMARIZER_API_KEY_ENV} override for context summarisation.
 *
 * Required: `PI_SUMMARIZER_BASE_URL`, `PI_SUMMARIZER_MODEL`, `PI_SUMMARIZER_API_KEY`.
 *
 * Returns `undefined` when no override is configured (silent fallback to the main model).
 * Returns `undefined` with a `console.warn` when any required var is missing or empty —
 * partial configs are surfaced loudly rather than silently dropping a half-configured override.
 */
export function resolveSummariserEnv(env?: ProviderEnv): SummariserEnvOverride | undefined {
	const baseUrl = getProviderEnvValue(PI_SUMMARIZER_BASE_URL_ENV, env)?.trim();
	const model = getProviderEnvValue(PI_SUMMARIZER_MODEL_ENV, env)?.trim();
	const apiKey = getProviderEnvValue(PI_SUMMARIZER_API_KEY_ENV, env)?.trim();

	if (!baseUrl && !model && !apiKey) return undefined;

	if (!baseUrl || !model || !apiKey) {
		const missing = [
			!baseUrl && PI_SUMMARIZER_BASE_URL_ENV,
			!model && PI_SUMMARIZER_MODEL_ENV,
			!apiKey && PI_SUMMARIZER_API_KEY_ENV,
		].filter((name): name is string => !!name);
		console.warn(
			`[pi] PI_SUMMARIZER_* override is incomplete (missing: ${missing.join(", ")}). ` +
				"Falling back to the main model for context summarisation.",
		);
		return undefined;
	}

	return { model: model, baseUrl: baseUrl, apiKey: apiKey };
}

import { resolveSummariserEnv } from "./summariser-env.ts";
import type { Model, ProviderEnv } from "./types.ts";

const SUMMARISER_DEFAULT_PROVIDER = "pi-summariser-override";
const SUMMARISER_DEFAULT_CONTEXT_WINDOW = 128000;
const SUMMARISER_DEFAULT_MAX_TOKENS = 8192;

/** Stable provider id used to register the override model on a `MutableModels` collection. */
export const SUMMARISER_OVERRIDE_PROVIDER_ID = SUMMARISER_DEFAULT_PROVIDER;

/** Resolved PI_SUMMARIZER_* override: a one-off model + the api key used to call it. */
export interface SummariserModelOverride {
	/** OpenAI-compatible model pointed at the override base URL. */
	model: Model<"openai-completions">;
	/** API key used to authenticate against the override endpoint. */
	apiKey: string;
}

/**
 * Resolve a Model<"openai-completions"> + API key that the summariser should use
 * when the `PI_SUMMARIZER_*` env-var override is configured.
 *
 * Returns `undefined` when no override is configured (or only a partial set is
 * present); callers should fall back to the main agent model in that case.
 *
 * The returned model targets an OpenAI-compatible API at the configured base
 * URL so DeepSeek, vLLM, OpenRouter, llama.cpp, and similar proxies work
 * without per-provider plumbing. The caller is responsible for registering the
 * provider on a `MutableModels` before issuing any request.
 */
export function resolveSummariserModel(env?: ProviderEnv): SummariserModelOverride | undefined {
	const override = resolveSummariserEnv(env);
	if (!override) return undefined;

	const model: Model<"openai-completions"> = {
		id: override.model,
		name: `${override.model} (PI summariser override)`,
		api: "openai-completions",
		provider: SUMMARISER_DEFAULT_PROVIDER,
		baseUrl: override.baseUrl,
		reasoning: false,
		input: ["text"],
		// Cost unknown for arbitrary endpoints; zero is conservative so /usage
		// surfaces don't over-report spend on the override model.
		cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
		contextWindow: SUMMARISER_DEFAULT_CONTEXT_WINDOW,
		maxTokens: SUMMARISER_DEFAULT_MAX_TOKENS,
	};
	return { model, apiKey: override.apiKey };
}

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
	PI_SUMMARIZER_API_KEY_ENV,
	PI_SUMMARIZER_BASE_URL_ENV,
	PI_SUMMARIZER_MODEL_ENV,
	resolveSummariserEnv,
} from "../src/summariser-env.ts";

const ENV_KEYS = [PI_SUMMARIZER_BASE_URL_ENV, PI_SUMMARIZER_MODEL_ENV, PI_SUMMARIZER_API_KEY_ENV] as const;

const originalEnv: Record<string, string | undefined> = {};

beforeEach(() => {
	for (const key of ENV_KEYS) originalEnv[key] = process.env[key];
	for (const key of ENV_KEYS) delete process.env[key];
	vi.spyOn(console, "warn").mockImplementation(() => {});
});

afterEach(() => {
	for (const key of ENV_KEYS) {
		const original = originalEnv[key];
		if (original === undefined) delete process.env[key];
		else process.env[key] = original;
	}
	vi.restoreAllMocks();
});

describe("resolveSummariserEnv", () => {
	it("returns undefined when no PI_SUMMARIZER_* env vars are set (fall back to main model)", () => {
		expect(resolveSummariserEnv()).toBeUndefined();
		expect(console.warn).not.toHaveBeenCalled();
	});

	it("returns undefined and warns when only PI_SUMMARIZER_BASE_URL + PI_SUMMARIZER_MODEL are set", () => {
		process.env[PI_SUMMARIZER_BASE_URL_ENV] = "https://api.deepseek.com/v1";
		process.env[PI_SUMMARIZER_MODEL_ENV] = "deepseek-chat";
		expect(resolveSummariserEnv()).toBeUndefined();
		expect(console.warn).toHaveBeenCalledTimes(1);
		expect(console.warn).toHaveBeenCalledWith(expect.stringContaining(PI_SUMMARIZER_API_KEY_ENV));
	});

	it("returns undefined and warns when only PI_SUMMARIZER_API_KEY is set", () => {
		process.env[PI_SUMMARIZER_API_KEY_ENV] = "sk-test";
		expect(resolveSummariserEnv()).toBeUndefined();
		expect(console.warn).toHaveBeenCalledTimes(1);
		expect(console.warn).toHaveBeenCalledWith(expect.stringContaining(PI_SUMMARIZER_BASE_URL_ENV));
	});

	it("treats empty-string values as missing (no partial set accepted)", () => {
		process.env[PI_SUMMARIZER_BASE_URL_ENV] = "   ";
		process.env[PI_SUMMARIZER_MODEL_ENV] = "deepseek-chat";
		process.env[PI_SUMMARIZER_API_KEY_ENV] = "sk-test";
		expect(resolveSummariserEnv()).toBeUndefined();
		expect(console.warn).toHaveBeenCalledTimes(1);
		expect(console.warn).toHaveBeenCalledWith(expect.stringContaining(PI_SUMMARIZER_BASE_URL_ENV));
	});

	it("returns the override when the three required vars are set", () => {
		process.env[PI_SUMMARIZER_BASE_URL_ENV] = "https://api.deepseek.com/v1";
		process.env[PI_SUMMARIZER_MODEL_ENV] = "deepseek-chat";
		process.env[PI_SUMMARIZER_API_KEY_ENV] = "sk-test";
		const result = resolveSummariserEnv();
		expect(result).toEqual({
			baseUrl: "https://api.deepseek.com/v1",
			model: "deepseek-chat",
			apiKey: "sk-test",
		});
		expect(console.warn).not.toHaveBeenCalled();
	});

	it("trims whitespace around each env value before returning", () => {
		process.env[PI_SUMMARIZER_BASE_URL_ENV] = "  https://api.deepseek.com/v1  ";
		process.env[PI_SUMMARIZER_MODEL_ENV] = "\tdeepseek-chat\n";
		process.env[PI_SUMMARIZER_API_KEY_ENV] = " sk-test ";
		expect(resolveSummariserEnv()).toEqual({
			baseUrl: "https://api.deepseek.com/v1",
			model: "deepseek-chat",
			apiKey: "sk-test",
		});
	});

	it("accepts an explicit ProviderEnv object instead of reading process.env", () => {
		const result = resolveSummariserEnv({
			[PI_SUMMARIZER_BASE_URL_ENV]: "https://api.deepseek.com/v1",
			[PI_SUMMARIZER_MODEL_ENV]: "deepseek-chat",
			[PI_SUMMARIZER_API_KEY_ENV]: "sk-test",
		});
		expect(result).toEqual({
			baseUrl: "https://api.deepseek.com/v1",
			model: "deepseek-chat",
			apiKey: "sk-test",
		});
	});
});

